const $=id=>document.getElementById(id);let saved=normalizeSave();try{saved=normalizeSave(JSON.parse(localStorage.getItem('cellguard-v1')||'{}'))}catch{}
const notifyUpgrade=createUpgradeNotifier();const allies=[],hazards=[];let reproduceCD=0,stageTime=0,hazardCD=10;let lastWin=false;let passageOpen=0,pausedFrom='play';
let selected=saved.unlocked,mode='menu',lastMode='menu',stage=0,wave=0,hp=100,maxHp=100,kills=0,earned=0,shot=0,inv=0,dodgeCD=0,pulseCD=0,squeezeCD=0,clearTimer=0,clock=0;const keys={},enemies=[],bullets=[],drops=[],fx=[];let lastDir=new T.Vector3(0,0,-1);const scene=new T.Scene();scene.background=new T.Color(0x102525);scene.fog=new T.FogExp2(0x102525,.022);const renderer=createRenderer();renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;const camera=new T.PerspectiveCamera(42,innerWidth/innerHeight,.1,140);scene.add(new T.HemisphereLight(0xd8ffd7,0x354b4b,2.2));const light=new T.DirectionalLight(0xfff6db,3);light.position.set(8,20,9);light.castShadow=true;light.shadow.mapSize.set(1024,1024);Object.assign(light.shadow.camera,{left:-22,right:22,top:22,bottom:-22});scene.add(light);const materials={};function mat(c){return materials[c]||(materials[c]=new T.MeshStandardMaterial({color:c,flatShading:true,roughness:.8}))}const geoCache=new Map();function mesh(g,c,x=0,y=0,z=0,parent=scene){const key=g.type+JSON.stringify(g.parameters||{});if(geoCache.has(key)){if(geoCache.get(key)!==g)g.dispose();g=geoCache.get(key)}else geoCache.set(key,g);let m=new T.Mesh(g,mat(c));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}const sphere=new T.IcosahedronGeometry(1,1),smallSphere=new T.IcosahedronGeometry(1,0);const arena=new T.Group();scene.add(arena);const floor=mesh(new T.CylinderGeometry(22,23,1,48),0x274d48,0,-.7,0,arena);for(let i=0;i<48;i++){let a=i/48*Math.PI*2;let m=mesh(sphere,i%2?0x355c50:0x426958,Math.cos(a)*22,.4,Math.sin(a)*22,arena);m.scale.set(1.6,1+i%3*.35,1.5)}for(let i=0;i<60;i++){let a=i*2.4,r=5+Math.random()*16;const m=mesh(new T.CylinderGeometry(.55,.65,.18,8),0x81585c,Math.cos(a)*r,-.05,Math.sin(a)*r,arena);m.rotation.z=Math.random()*.2}const wall=new T.Group();arena.add(wall);for(let z=-17;z<=17;z+=1.25){let m=mesh(sphere,0x709e82,0,.7,z,wall);m.scale.set(.4,1.05,.7)}
function cell(isEnemy=false,type=0){const g=new T.Group();let c=isEnemy?enemyTypes[type].color:0xe6edd6;const body=mesh(sphere,c,0,0,0,g);body.scale.set(isEnemy&&type===5?1.65:1.13,isEnemy&&type===7?.75:1,1);if(isEnemy&&type===3){for(let i=0;i<3;i++){const lobe=mesh(smallSphere,c,Math.cos(i*2)*.8,.1,Math.sin(i*2)*.8,g);lobe.scale.setScalar(.55)}}if(isEnemy&&type===4){const shell=mesh(new T.OctahedronGeometry(1.25),0x527f8e,0,0,0,g);shell.scale.set(1,.85,.8)}if(isEnemy){for(let i=0;i<9;i++){let a=i/9*Math.PI*2;const s=mesh(new T.ConeGeometry(.17,.65,5),c,Math.cos(a),Math.sin(a),0,g);s.rotation.z=a-Math.PI/2}}else{for(let i=0;i<4;i++){const s=mesh(smallSphere,0xb0cab0,Math.cos(i*2.4)*.6,.75,Math.sin(i*2.4)*.5,g);s.scale.setScalar(.27)}}for(let x of [-.35,.35]){let e=mesh(sphere,0x203b35,x,.19,.86,g);e.scale.set(.12,.18,.08);let gl=mesh(smallSphere,0xffffff,x-.025,.25,.92,g);gl.scale.setScalar(.035)}let mouth=mesh(new T.TorusGeometry(.2,.035,4,8,Math.PI),0x203b35,0,-.15,.94,g);mouth.rotation.z=Math.PI;scene.add(g);return g}const player=cell();player.position.set(-4,1.2,0);const ring=mesh(new T.TorusGeometry(1.55,.025,5,60),0xc2f678,-4,-.13,0);ring.rotation.x=Math.PI/2;const portal=mesh(new T.TorusGeometry(2,.12,6,32),0xc2f678,0,2,0);portal.rotation.y=Math.PI/2;const portalGlow=mesh(new T.CircleGeometry(2,32),0x98d96d,0,2,0);portalGlow.rotation.y=Math.PI/2;portalGlow.material=new T.MeshBasicMaterial({color:0xc2f678,transparent:true,opacity:.13,side:T.DoubleSide});
