 if(win){for(const d of [...drops])bankDrop(d);awardDNA(saved,30+stage*3);earned+=30+stage*3;saved.unlocked=Math.min(levels.length-1,Math.max(saved.unlocked,stage+1));save();for(const a of [bullets,hazards,allies])clearObjects(a);
 if(stage<levels.length-1){mode='cleared';clearKeys();wall.visible=false;passageOpen=0;$('modal').hidden=true;$('bossHud').hidden=true;$('passageHint').hidden=false;$('passageHint').textContent=`${levels[stage].name} cleared! Walk through the passageway → ${levels[stage+1].name}`;toast('Infection cleared — the passage to the next organ is opening!');return}}
 mode='result';clearKeys();$('modal').hidden=false;$('modalTag').textContent=win?'BODY PROTECTED':'CELL DOWN';$('modalTitle').textContent=win?'Body protected!':'A new cell can try again';$('modalText').textContent=`${kills} enemies defeated · ${earned} DNA collected. ${win?'You completed all 30 stages!':'Your DNA is safe. Retry this organ with your upgrades.'}`;$('modalBody').innerHTML='';$('closeModal').textContent=win?'Return to title':'Retry this organ';$('closeModal').onclick=win?goMenu:start;
