function update(dt){clock+=dt;if(mode==='menu'){if(notifyUpgrade(saved)){upgrades(true);return}camera.position.set(22,22,29);camera.lookAt(-1,0,0);player.rotation.y=Math.sin(clock*.4)*.35;player.position.y=1.4+Math.sin(clock*2)*.15;player.scale.lerp(new T.Vector3(2.5,2.5,2.5),.08);ring.scale.setScalar(2);arena.rotation.y=0;return}if(mode==='cleared'){updatePassage(dt);return}if(mode!=='play')return;camera.lookAt(0,0,0);ring.scale.setScalar(1);player.scale.lerp(new T.Vector3(1,1,1),.15);shot-=dt;inv-=dt;dodgeCD-=dt;pulseCD-=dt;squeezeCD-=dt;reproduceCD-=dt;stageTime+=dt;hazardCD-=dt;updateAllies(dt);updateHazards(dt);if(hazardCD<=0){organHazard();hazardCD=12}const dir=new T.Vector3((keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),0,(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0));if(dir.lengthSq()){dir.normalize();lastDir.copy(dir);const oldX=player.position.x;player.position.addScaledVector(dir,movementSpeed(saved)*dt);if(Math.abs(player.position.x)<1.25||oldX*player.position.x<0)player.position.x=Math.sign(oldX)*1.25;player.rotation.y=Math.atan2(dir.x,dir.z)}if(player.position.length()>20){const p=new T.Vector3(player.position.x,0,player.position.z).setLength(20);player.position.x=p.x;player.position.z=p.z}player.position.y=1.15+Math.sin(clock*8)*.07;player.visible=inv<=0||Math.floor(clock*18)%2===0;ring.position.set(player.position.x,-.13,player.position.z);if(keys[' ']&&shot<=0)fire();for(const e of [...enemies]){updateEnemy(e,dt);if(mode!=='play')break}if(mode!=='play')return;for(const b of [...bullets]){b.mesh.position.addScaledVector(b.v,dt);b.life-=dt;if(b.hostile){if(b.mesh.position.distanceTo(player.position)<1){damage(b.damage);b.life=0}}else for(const e of [...enemies])if(b.mesh.position.distanceTo(e.mesh.position)<e.r+.25){hurtEnemy(e,b.damage);b.life=0;break}if(b.life<=0){scene.remove(b.mesh);bullets.splice(bullets.indexOf(b),1)}}for(const d of [...drops]){d.mesh.rotation.y+=dt*2;let dist=d.mesh.position.distanceTo(player.position);if(dist<5)d.mesh.position.lerp(player.position,dt*4);if(dist<1.5)bankDrop(d)}if(enemies.length===0){clearTimer+=dt;if(clearTimer>2){clearTimer=0;if(wave<levels[stage].waves){hp=Math.min(maxHp,hp+20);spawnWave()}else end(true)}}$('hpText').textContent=Math.ceil(hp)+' / '+maxHp;$('hpbar').style.width=hp/maxHp*100+'%';$('dna').textContent=`${saved.dna} / ${cellCapacity(saved)}`;$('dnaReserve').textContent=saved.reserve?`${saved.reserve} extra DNA waiting · upgrade vacuole`:'';$('wave').textContent=`${levels[stage].name} · Wave ${wave}/${levels[stage].waves} · ${enemies.length} enemies`;$('objective').textContent=`Dodge ${dodgeCD>0?Math.ceil(dodgeCD)+'s':'ready'} · Squeeze ${squeezeCD>0?Math.ceil(squeezeCD)+'s':'ready'} · Pulse ${pulseCD>0?Math.ceil(pulseCD)+'s':'ready'}`;updateExtraHUD();if(mode==='play'&&notifyUpgrade(saved))upgrades(true);}
let prev=performance.now();function frame(now){requestAnimationFrame(frame);let dt=Math.min((now-prev)/1000,.15);prev=now;for(let remaining=dt;remaining>0;remaining-=.025)update(Math.min(.025,remaining));if(mode==='play'||mode==='menu'){for(const f of [...fx]){f.life-=dt;f.mesh.position.addScaledVector(f.v,dt);f.mesh.scale.multiplyScalar(.97);if(f.life<=0){scene.remove(f.mesh);fx.splice(fx.indexOf(f),1)}}}if(mode!=='play')player.visible=true;portal.rotation.x=Math.sin(clock)*.05;renderer.render(scene,camera)}function resize(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix()}window.addEventListener('resize',resize);resize();requestAnimationFrame(frame);

function createRenderer(){try{return new T.WebGLRenderer({canvas:$('world'),antialias:true})}catch{const old=$('world'),canvas=old.cloneNode();old.replaceWith(canvas);const ctx=canvas.getContext('2d'),faceCache=new WeakMap();return {shadowMap:{},setPixelRatio(){},setSize(w,h){canvas.width=w;canvas.height=h},render(scene,camera){scene.updateMatrixWorld();camera.updateMatrixWorld();const vp=new T.Matrix4().multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse),faces=[];ctx.fillStyle='#102525';ctx.fillRect(0,0,canvas.width,canvas.height);scene.traverse(o=>{if(!o.isMesh)return;for(let ancestor=o;ancestor;ancestor=ancestor.parent)if(!ancestor.visible)return;const cacheKey=o.matrixWorld.elements.join(',')+vp.elements.join(',')+o.material.color.getHex()+canvas.width+','+canvas.height;const cached=faceCache.get(o);if(cached?.key===cacheKey){faces.push(...cached.faces);return}const objectFaces=[];const pos=o.geometry.attributes.position,idx=o.geometry.index,trans=new T.Matrix4().multiplyMatrices(vp,o.matrixWorld),count=idx?idx.count:pos.count;for(let i=0;i<count;i+=3){const pts=[],world=[];for(let j=0;j<3;j++){const k=idx?idx.getX(i+j):i+j;const v=new T.Vector3().fromBufferAttribute(pos,k);world.push(v.clone().applyMatrix4(o.matrixWorld));pts.push(v.applyMatrix4(trans))}if(pts.some(v=>v.z>1||v.z< -1))continue;const normal=new T.Vector3().subVectors(world[1],world[0]).cross(new T.Vector3().subVectors(world[2],world[0])).normalize();if(o.material.side!==T.DoubleSide&&normal.dot(camera.position.clone().sub(world[0]))<=0)continue;const shade=.58+.42*Math.max(0,normal.dot(new T.Vector3(.35,.85,.4)));const col=o.material.color.clone().multiplyScalar(shade);objectFaces.push({pts,z:o===floor?2:(pts[0].z+pts[1].z+pts[2].z)/3,c:col.getStyle(),a:o.material.opacity})}faceCache.set(o,{key:cacheKey,faces:objectFaces});faces.push(...objectFaces)});faces.sort((a,b)=>b.z-a.z);for(const f of faces){ctx.globalAlpha=f.a;ctx.fillStyle=f.c;ctx.beginPath();f.pts.forEach((p,i)=>{const x=(p.x+1)*canvas.width/2,y=(1-p.y)*canvas.height/2;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.closePath();ctx.fill()}ctx.globalAlpha=1}}}}

function reproduce(){if(reproduceCD>0){toast(`Reproduce ready in ${Math.ceil(reproduceCD)}s`);return}clearObjects(allies);const n=Math.max(1,Math.floor(Math.min(6,2+saved.up[3])/1.5));for(let i=0;i<n;i++){const m=cell();m.scale.setScalar(.6);m.position.copy(player.position);allies.push({mesh:m,life:12+saved.up[3]*2,cd:i*.15,angle:i/n*Math.PI*2})}reproduceCD=Math.ceil(Math.max(18,28-saved.up[3])*1.5);burst(player.position,0xc2f678,25);toast(`${n} helper cell${n===1?'':'s'} reproduced! Automatic attacks active.`)}
function updateAllies(dt){for(const a of [...allies]){a.life-=dt;if(a.life<=0){scene.remove(a.mesh);allies.splice(allies.indexOf(a),1);continue}a.angle+=dt*.7;const target=player.position.clone().add(new T.Vector3(Math.cos(a.angle)*2,0,Math.sin(a.angle)*2));a.mesh.position.lerp(target,Math.min(1,dt*5));a.cd-=dt;const nearest=enemies.reduce((best,e)=>!best||e.mesh.position.distanceTo(a.mesh.position)<best.mesh.position.distanceTo(a.mesh.position)?e:best,null);if(nearest&&a.cd<=0){const d=nearest.mesh.position.clone().sub(a.mesh.position).normalize();a.mesh.rotation.y=Math.atan2(d.x,d.z);projectile(a.mesh.position,d,false,19,5+saved.up[0]*2);a.cd=.65}}}
function pool(pos,r=2.5,color=0xc99c58,life=4){if(hazards.length>=12)return;const m=mesh(new T.CylinderGeometry(r,r,.08,24),color,pos.x,.03,pos.z);hazards.push({mesh:m,r,life,warm:.9,tick:0})}
function updateHazards(dt){for(const h of [...hazards]){h.life-=dt;h.warm-=dt;h.tick-=dt;h.mesh.scale.setScalar(h.warm>0?.8+Math.sin(clock*18)*.15:1);if(h.warm<=0&&h.tick<=0&&Math.hypot(player.position.x-h.mesh.position.x,player.position.z-h.mesh.position.z)<h.r){damage(8);h.tick=.8}if(h.life<=0){scene.remove(h.mesh);hazards.splice(hazards.indexOf(h),1)}}}
function organHazard(){const kind=levels[stage].hazard;if(kind==='air'||kind==='current'){toast(kind==='air'?'Airway surge — watch the marked zones!':'Bloodstream surge — leave the marked zones!')}pool(player.position.clone(),kind==='pulse'?3.6:2.8,kind==='acid'?0xb8b859:kind==='pulse'?0xb76b85:kind==='current'?0x619eaf:0x9985b9,kind==='pulse'?2.5:4);}
function updateEnemy(e,dt){const pos=e.mesh.position,d=player.position.clone().sub(pos);d.y=0;const dist=d.length();d.normalize();e.special-=dt;e.charge-=dt;if(e.windup>0){e.windup-=dt;if(e.windup<=0)e.charge=.65}const oldX=pos.x;if(e.windup>0){e.mesh.scale.setScalar(e.r*(1+Math.sin(clock*20)*.04))}else if(e.charge>0&&e.chargeDir){pos.addScaledVector(e.chargeDir,dt*9)}else if(e.charge>-0.75&&e.chargeDir){/* charge recovery */}else{e.chargeDir=null;e.mesh.scale.setScalar(e.r);pos.addScaledVector(d,e.speed*dt)}if(Math.abs(pos.x)<1.25||oldX*pos.x<0)pos.x=Math.sign(oldX||1)*1.25;const length=Math.hypot(pos.x,pos.z);if(length>20){pos.x*=20/length;pos.z*=20/length}e.mesh.rotation.y=Math.atan2(d.x,d.z);pos.y=e.r+Math.sin(clock*4+e.cd)*.1;
 if(dist<e.r+.8){if(e.type===5&&inv<=0)e.hp=Math.min(e.maxHp,e.hp+8);damage(e.boss?18:9)}
 const ability=enemyTypes[e.type].ability;if(e.special<=0){if(ability==='dash'||e.boss){e.chargeDir=d.clone();e.windup=.8;e.charge=-2;pool(player.position.clone(),e.boss?2.4:1.6,0xd39162,1.6)}if(ability==='poison')pool(pos.clone(),2.3,0x9581be,5);if(e.boss&&e.summons<3){const l=levels[stage];spawnEnemy(l.enemies[e.summons%l.enemies.length],pos.clone().add(new T.Vector3(0,0,2)),'normal',1);e.summons++}e.special=e.boss?7:6;}
 e.cd-=dt;if(e.cd<=0&&(e.boss||['spit','burst','poison'].includes(ability))){const origin=pos.clone();origin.y=1.15;const aim=player.position.clone().sub(origin).normalize();if(ability==='burst'||e.boss){const count=e.rank==='boss'?10:e.rank==='mini'?7:6;for(let i=0;i<count;i++){const angle=i/count*Math.PI*2+clock*.2;projectile(origin,new T.Vector3(Math.cos(angle),0,Math.sin(angle)),true,5.5,e.boss?12:7)}}else projectile(origin,aim,true,6,9);e.cd=e.rank==='boss'?2:e.rank==='mini'?2.6:3;}
}
function updateExtraHUD(){const boss=enemies.find(e=>e.boss);$('bossHud').hidden=!boss;if(boss){$('bossName').textContent=boss.rank==='boss'?levels[stage].boss:'Elite '+enemyTypes[boss.type].name;$('bossHP').textContent=Math.ceil(boss.hp)+' / '+boss.maxHp;$('bossbar').style.width=Math.max(0,boss.hp/boss.maxHp*100)+'%'}$('reproduce').textContent=reproduceCD>0?`R · Reproduce ${Math.ceil(reproduceCD)}s`:'R · Reproduce ready';$('reproduce').disabled=reproduceCD>0;$('helperCount').textContent=`${allies.length} helper${allies.length===1?'':'s'} · ${Math.floor(stageTime/60)}:${String(Math.floor(stageTime%60)).padStart(2,'0')}`;}

function dnaHelix(growth){const scale=.75+growth/24*.85;let strands=['',''],rungs='';for(let i=0;i<=24;i++){let y=100+i*12,phase=i*.4,x=170+Math.sin(phase)*65,z=170-Math.sin(phase)*65;strands[0]+=(i?' L':'M')+x+','+y;strands[1]+=(i?' L':'M')+z+','+y;if(i%2===0)rungs+=`<path d="M${x},${y}H${z}" stroke="#8ac8ac" stroke-width="5"/><circle cx="${x}" cy="${y}" r="8" fill="#c2f678"/><circle cx="${z}" cy="${y}" r="8" fill="#a1def3"/>`}return `<svg class="dna-helix" viewBox="0 0 340 490" role="img" aria-label="DNA double helix, growth level ${growth} of 24"><g transform="translate(170 245) scale(${scale}) translate(-170 -245)"><path d="${strands[0]}" fill="none" stroke="#c2f678" stroke-width="7"/><path d="${strands[1]}" fill="none" stroke="#a1def3" stroke-width="7"/>${rungs}</g></svg>`}

function openCell(){if(!['menu','play','cleared','paused','upgrade'].includes(mode))return;cellReturnMode=mode;mode='cell';clearKeys();if(cellReturnMode==='upgrade'||cellReturnMode==='paused')$('modal').hidden=true;$('cellView').hidden=false;drawCell()}
function closeCell(){$('cellView').hidden=true;mode=cellReturnMode;clearKeys();if(mode==='upgrade'){drawUpgrades();$('modal').hidden=false}else if(mode==='paused'){$('modal').hidden=false}menuUI()}
function drawCell(){const [v,m]=saved.organelles,cap=cellCapacity(saved),speed=movementSpeed(saved);$('cellBalance').textContent=`${saved.dna} / ${cap} DNA`;$('cellReserve').textContent=saved.reserve?`${saved.reserve} extra DNA is waiting. It moves into storage when there is room.`:'Extra DNA waits safely when storage is full.';$('vacuoleLevel').textContent=`LEVEL ${v} / ${MAX_UPGRADE}`;$('mitoLevel').textContent=`LEVEL ${m} / ${MAX_UPGRADE}`;$('vacuoleValue').textContent=`Stores ${cap} DNA`;$('mitoValue').textContent=`Movement speed: ${speed.toFixed(1)} (${100+m*10}%)`;$('vacuoleNext').textContent=v<MAX_UPGRADE?`Next: ${cap+300} DNA capacity`:'Maximum storage reached';$('mitoNext').textContent=m<MAX_UPGRADE?`Next: ${100+(m+1)*10}% movement speed`:'Maximum speed reached';for(let i=0;i<2;i++){let b=$(i?'buyMito':'buyVacuole'),level=saved.organelles[i],price=upgradeCost(level);b.disabled=level>=MAX_UPGRADE||saved.dna<price;b.textContent=level>=MAX_UPGRADE?'MAX LEVEL':`Upgrade · ${price} DNA`;b.onclick=()=>{if(buyOrganelle(saved,i)){save();drawCell();menuUI()}}}const scale=1+v*.09;$('vacuoleIllustration').setAttribute('transform',`translate(330 280) scale(${scale}) translate(-330 -280)`);$('cellBackLabel').textContent=cellReturnMode==='upgrade'?'Back to evolution':cellReturnMode==='menu'?'Back to journey':'Resume game'}
